// Key lanes K1, package P6 (plan v4 5.2 "Census test"): every normalize, family-guard and
// key-preference call site in server/ and shared/ (non-test, comments stripped) is classified
// Accept, Closed or Reject. A NEW site, a moved site, or a changed line fails here until it is
// classified. Generated by P6 at its own branch (K0-C's census.json was not committed when P6
// was built), then checked by hand against plan 5.2.
//
// Keyed by file, function and the exact trimmed line text (never a line number, which drifts),
// with the number of calls on that line.
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'

type Rule = 'accept' | 'closed' | 'reject'
type CensusRow = [file: string, fn: string, calls: number, line: string, rule: Rule, note: string]

const ROOT = resolve(fileURLToPath(new URL('.', import.meta.url)), '..', '..')
export const CENSUS_FUNCTIONS = [
  'normalizeModelPreference', 'isModelPreference', 'isClaudeModel', 'isCodexModel', 'isCursorModel', 'isOllamaModel',
  'parsePreference', 'isProfilePreference', 'parseV1KeyModelName',
  'normalizeSessionBinding', 'requestBinding', 'closedEnvDefaultModel', 'keyProfileRejectApplies', 'steerProviderFor',
] as const
const CALL_RE = new RegExp(`(?<![\\w.])(?<!function )(${CENSUS_FUNCTIONS.join('|')})\\(`, 'g')

function* sources(dir: string): Generator<string> {
  for (const entry of readdirSync(dir)) {
    if (['node_modules', 'data', 'dist', '__fixtures__'].includes(entry)) continue
    const path = join(dir, entry)
    if (statSync(path).isDirectory()) yield* sources(path)
    else if (path.endsWith('.ts') && !path.endsWith('.test.ts') && !path.endsWith('.d.ts')) yield path
  }
}

/** Block comments blanked (line count kept), line comments cut. Good enough for this codebase's style. */
function codeLines(text: string): string[] {
  return text.replace(/\/\*[\s\S]*?\*\//g, m => m.replace(/[^\n]/g, ' '))
    .split('\n').map(line => line.replace(/(^|[^:'"`\\])\/\/.*$/, '$1'))
}

export function scanCensus(root = ROOT): Map<string, number> {
  const found = new Map<string, number>()
  for (const dir of ['server', 'shared']) for (const file of sources(join(root, dir))) {
    for (const line of codeLines(readFileSync(file, 'utf8'))) {
      const counts = new Map<string, number>()
      for (const m of line.matchAll(CALL_RE)) counts.set(m[1], (counts.get(m[1]) ?? 0) + 1)
      for (const [fn, n] of counts) {
        const key = `${relative(root, file)} | ${fn} | ${line.trim()}`
        found.set(key, (found.get(key) ?? 0) + n)
      }
    }
  }
  return found
}

