describe('P6 preference census (plan 5.2)', () => {
  it('every call site is classified, and every classified site still exists exactly as listed', () => {
    const found = scanCensus()
    const listed = new Map<string, number>()
    for (const [file, fn, calls, line] of CENSUS) {
      const key = `${file} | ${fn} | ${line}`
      listed.set(key, (listed.get(key) ?? 0) + calls)
    }
    const unclassified = [...found].filter(([k, n]) => listed.get(k) !== n).map(([k, n]) => `${n}x ${k}`)
    const gone = [...listed].filter(([k, n]) => found.get(k) !== n).map(([k, n]) => `${n}x ${k}`)
    expect({ unclassified, gone }).toEqual({ unclassified: [], gone: [] })
  })

  it('parsePreference is called only at the Accept sites the plan allows', () => {
    const files = new Set([...scanCensus().keys()].filter(k => k.split(' | ')[1] === 'parsePreference').map(k => k.split(' | ')[0]))
    expect([...files].filter(f => !PARSE_PREFERENCE_ALLOWED.has(f))).toEqual([])
    for (const [file, fn, , , rule] of CENSUS) if (fn === 'parsePreference') expect({ file, rule }).toEqual({ file, rule: 'accept' })
  })

  it('isModelPreference stays closed: only normalizeModelPreference calls it', () => {
    const sites = CENSUS.filter(r => r[1] === 'isModelPreference')
    expect(sites.map(r => [r[0], r[4]])).toEqual([['shared/model-preference.ts', 'closed']])
  })

  it('the plan 5.2 Reject and Closed sites are classified as such', () => {
    const ruleOf = (file: string) => new Set(CENSUS.filter(r => r[0] === file && /normalize|Reject|steerProvider|parseV1|requestBinding|parsePreference|closedEnv/.test(r[1])).map(r => r[4]))
    for (const f of ['server/lib/morning-brief-config.ts', 'server/lib/work-handoff-requests.ts', 'server/lib/task-store.ts']) expect([f, [...new Set(CENSUS.filter(r => r[0] === f).map(r => r[4]))]]).toEqual([f, ['reject']])
    for (const f of ['server/routes/work-handoff-requests.ts', 'server/lib/control2-draft.ts', 'server/lib/handoff-store.ts', 'server/lib/codex-engine-sessions.ts', 'server/lib/cursor-engine-sessions.ts', 'server/routes/cli-debug.ts']) {
      expect([f, [...ruleOf(f)]]).toEqual([f, ['closed']])
    }
    // claude-steer's closed functions plus one explicit guard; openai-compat's closed resolveModel plus cos-key.
    expect(CENSUS.filter(r => r[0] === 'server/lib/claude-steer.ts' && r[4] === 'accept').every(r => r[1] === 'parsePreference')).toBe(true)
    expect(CENSUS.filter(r => r[0] === 'server/routes/openai-compat.ts' && r[4] === 'accept').map(r => r[1])).toEqual(['parseV1KeyModelName'])
  })

  it('a new site fails the census (the check can fail)', () => {
    const found = scanCensus()
    const fake = new Map(found)
    fake.set('server/lib/brand-new.ts | normalizeModelPreference | const m = normalizeModelPreference(x)', 1)
    const listed = new Set(CENSUS.map(([file, fn, , line]) => `${file} | ${fn} | ${line}`))
    expect([...fake.keys()].filter(k => !listed.has(k))).toEqual(['server/lib/brand-new.ts | normalizeModelPreference | const m = normalizeModelPreference(x)'])
  })
})
